package com.example.mynotes;

public class Note {
    private String id;
    private String title;
    private String content;
    private long timestamp;

    public Note(String id, String title, String content, long timestamp) {
        this.id = id;
        this.title = title;
        this.content = content;
        this.timestamp = timestamp;
    }

    public String getId() { return id; }
    public void setId(String id) { this.id = id; }

    public String getTitle() { return title; }
    public void setTitle(String title) { this.title = title; }

    public String getContent() { return content; }
    public void setContent(String content) { this.content = content; }

    public long getTimestamp() { return timestamp; }
    public void setTimestamp(long timestamp) { this.timestamp = timestamp; }
}

package com.example.mynotes;

import android.os.Bundle;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Toast;
import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;
import java.util.ArrayList;
import java.util.List;

public class MainActivity extends AppCompatActivity {

    private EditText editTitle, editContent;
    private Button btnSave;
    private RecyclerView recyclerViewNotes;
    private List<Note> noteList;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        editTitle = findViewById(R.id.editTitle);
        editContent = findViewById(R.id.editContent);
        btnSave = findViewById(R.id.btnSave);
        recyclerViewNotes = findViewById(R.id.recyclerViewNotes);

        noteList = new ArrayList<>();
        recyclerViewNotes.setLayoutManager(new LinearLayoutManager(this));

        btnSave.setOnClickListener(v -> {
            String title = editTitle.getText().toString().trim();
            String content = editContent.getText().toString().trim();

            if (title.isEmpty() || content.isEmpty()) {
                Toast.makeText(MainActivity.this, "Veuillez remplir tous les champs", Toast.LENGTH_SHORT).show();
                return;
            }

            Note newNote = new Note(String.valueOf(System.currentTimeMillis()), title, content, System.currentTimeMillis());
            noteList.add(newNote);

            editTitle.setText("");
            editContent.setText("");
            Toast.makeText(MainActivity.this, "Note enregistrée avec succès", Toast.LENGTH_SHORT).show();
        });
    }
}

